"""Experiment 9: generate zpd algebras as subalgebras of M_n(F_p) generated by idempotents
(Bresar Thm 2.27: finite-dim unital zpd <=> generated by idempotents), then test zJpd.
"""
import sys, random
sys.path.insert(0, '.')
from zpd import *


def mat_mult(X, Y, n, p):
    out = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if X[i][k]:
                xik = X[i][k]
                for j in range(n):
                    if Y[k][j]:
                        out[i][j] = (out[i][j] + xik * Y[k][j]) % p
    return out


def is_invertible(X, n, p):
    M = [row[:] for row in X]
    piv = 0
    for c in range(n):
        pp = None
        for r in range(piv, n):
            if M[r][c] % p:
                pp = r
                break
        if pp is None:
            return False
        M[piv], M[pp] = M[pp], M[piv]
        inv = pow(M[piv][c], p - 2, p)
        M[piv] = [(x * inv) % p for x in M[piv]]
        for r in range(n):
            if r != piv and M[r][c] % p:
                f = M[r][c]
                M[r] = [(a - f * b) % p for a, b in zip(M[r], M[piv])]
        piv += 1
    return True


def random_invertible(n, p, rng):
    while True:
        X = [[rng.randrange(p) for _ in range(n)] for _ in range(n)]
        if is_invertible(X, n, p):
            return X


def mat_inv(X, n, p):
    M = [row[:] + [1 if i == j else 0 for j in range(n)] for i, row in enumerate(X)]
    for c in range(n):
        pp = next(r for r in range(c, n) if M[r][c] % p)
        M[c], M[pp] = M[pp], M[c]
        inv = pow(M[c][c], p - 2, p)
        M[c] = [(x * inv) % p for x in M[c]]
        for r in range(n):
            if r != c and M[r][c] % p:
                f = M[r][c]
                M[r] = [(a - f * b) % p for a, b in zip(M[r], M[c])]
    return [row[n:] for row in M]


def random_idempotent(n, p, rng):
    """X P X^{-1} with P a diagonal 0/1 projection."""
    X = random_invertible(n, p, rng)
    Xi = mat_inv(X, n, p)
    P = [[1 if i == j and rng.random() < 0.5 else 0 for j in range(n)] for i in range(n)]
    return mat_mult(mat_mult(X, P, n, p), Xi, n, p)


def generated_algebra(n, p, gens):
    """span of all words in gens (and 1). Returns list of matrices (a basis)."""
    one = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    vecs = lambda X: [X[i][j] for i in range(n) for j in range(n)]
    mats = [one]
    vecbase = [vecs(one)]

    def in_span(vec):
        return rank(vecbase + [vec], p, len(vec)) == rank(vecbase, p, len(vec))
    cur = [one] + [g for g in gens]
    changed = True
    while changed:
        changed = False
        for A in list(cur):
            for B in list(cur):
                C = mat_mult(A, B, n, p)
                if not in_span(vecs(C)):
                    vecbase.append(vecs(C))
                    mats.append(C)
                    cur.append(C)
                    changed = True
    return mats


def algebra_from_basis(n, p, basis):
    """structure constants of span(basis) (matrices) in that basis."""
    m = len(basis)
    vecs = lambda X: [X[i][j] for i in range(n) for j in range(n)]
    T = [[[0] * m for _ in range(m)] for _ in range(m)]
    for a in range(m):
        for b in range(m):
            C = mat_mult(basis[a], basis[b], n, p)
            vec = vecs(C)
            # solve for coefficients in basis
            rows = [[basis[k][i][j] for k in range(m)] for i in range(n) for j in range(n)]
            rhs = vec
            # solve rows . c = rhs by elimination
            M = [rows[r][:] + [rhs[r]] for r in range(len(rows))]
            piv = 0
            sol = [0] * m
            where = []
            for c in range(m):
                pp = None
                for r in range(piv, len(M)):
                    if M[r][c] % p:
                        pp = r
                        break
                if pp is None:
                    continue
                M[piv], M[pp] = M[pp], M[piv]
                inv = pow(M[piv][c], p - 2, p)
                M[piv] = [(x * inv) % p for x in M[piv]]
                for r in range(len(M)):
                    if r != piv and M[r][c] % p:
                        f = M[r][c]
                        M[r] = [(aa - f * bb) % p for aa, bb in zip(M[r], M[piv])]
                where.append((c, piv))
                piv += 1
            for c, r in where:
                sol[c] = M[r][m] % p
            T[a][b] = sol
    return T


if __name__ == '__main__':
    p = int(sys.argv[1]) if len(sys.argv) > 1 else 3
    n = int(sys.argv[2]) if len(sys.argv) > 2 else 3
    trials = int(sys.argv[3]) if len(sys.argv) > 3 else 5
    rng = random.Random(2024)
    for t in range(trials):
        r = rng.choice([2, 2, 3])
        gens = [random_idempotent(n, p, rng) for _ in range(r)]
        basis = generated_algebra(n, p, gens)
        m = len(basis)
        if m < 4 or m > 7:
            continue
        T = algebra_from_basis(n, p, basis)
        dm = determined(m, T, p)
        dj = determined(m, jordan_mu_p(m, T, p), p)
        print(f"trial {t}: r={r} dim={m}  product {dm} zpd={dm[0]==dm[1]}  "
              f"Jordan {dj} zJpd={dj[0]==dj[1]}", flush=True)
